dtsPropsFor.Panel:
/** Standard gradient card surface. Accepts every intrinsic <div> prop. */
readonly className?: string;
readonly children?: React.ReactNode;
readonly style?: React.CSSProperties;
readonly id?: string;
readonly onClick?: React.MouseEventHandler<HTMLDivElement>;

dtsPropsFor.SectionLabel:
/** 10px uppercase tracked heading. Accepts every intrinsic <h3> prop. */
/** "dim" is the fainter section-divider tone; default "muted" is the card title. */
readonly tone?: "muted" | "dim";
readonly className?: string;
readonly children?: React.ReactNode;

dtsPropsFor.Stat:
/** Label-over-value KPI cell (MARK / DEBIT / UNREAL / DTE, net-greeks rows). */
readonly label: React.ReactNode;
readonly value: React.ReactNode;
/** Sign colour for the value line, e.g. "text-up" | "text-down" | "text-dim". */
readonly valueClassName?: string;
readonly className?: string;

dtsPropsFor.MetricChip:
/** Bordered pill for the global header strip (SPX, net gamma, flip, book P&L). */
readonly label: React.ReactNode;
readonly value: React.ReactNode;
readonly valueClassName?: string;
/** Swaps to the blood-dark danger surface (negative-gamma / loss emphasis). */
readonly alert?: boolean;
readonly className?: string;

dtsPropsFor.PanelHeading:
/** Title row inside a Panel: a SectionLabel, an optional inline badge, an optional right action. */
readonly title: React.ReactNode;
readonly badge?: React.ReactNode;
readonly action?: React.ReactNode;
readonly className?: string;

dtsPropsFor.ChipRail:
/** Below lg: a scroll-snap horizontal rail with a right-edge peek; at lg: reverts to flex-wrap. */
/** Each call site adds "snap-start shrink-0" to its own children. */
readonly children: React.ReactNode;
readonly ariaLabel: string;
readonly className?: string;

dtsPropsFor.ChartContainer:
/** Recharts responsive wrapper. Also supplies the chart context that ChartTooltipContent
 *  and ChartLegendContent read — both throw outside a ChartContainer.
 *  Give it a definite aspect-ratio, never a percentage height (a % height collapses to 0). */
readonly config: Record<string, { label?: React.ReactNode; icon?: React.ComponentType; color?: string; theme?: Record<"light" | "dark", string> }>;
readonly children: React.ReactElement;
readonly id?: string;
readonly className?: string;
readonly style?: React.CSSProperties;
readonly initialDimension?: { width: number; height: number };

dtsPropsFor.ChartTooltipContent:
/** Tooltip body for a recharts chart. Must be rendered inside a ChartContainer. */
readonly active?: boolean;
readonly payload?: readonly unknown[];
readonly label?: unknown;
readonly indicator?: "line" | "dot" | "dashed";
readonly hideLabel?: boolean;
readonly hideIndicator?: boolean;
readonly nameKey?: string;
readonly labelKey?: string;
readonly labelClassName?: string;
readonly className?: string;
readonly color?: string;

dtsPropsFor.ChartLegendContent:
/** Legend body for a recharts chart. Must be rendered inside a ChartContainer. */
readonly payload?: readonly unknown[];
readonly hideIcon?: boolean;
readonly nameKey?: string;
readonly verticalAlign?: "top" | "bottom";
readonly className?: string;

dtsPropsFor.LiveStatusBadge:
/** Current 3-state stream status. */
readonly status: "live" | "quiet" | "stalled";
/** Timestamp of the most recently received tick (null until the first tick). */
readonly lastTickAt: Date | null;
/** Server-pushed RTH truth from the last well-formed ping (null until the first ping). */
readonly isRth: boolean | null;
readonly hasReceivedFirstTick: boolean;
/** True while a manual reconnect is in flight. */
readonly isReconnecting: boolean;
/** Force-reconnect action (STALLED only). */
readonly onReconnect: () => void;

dtsPropsFor.CandidateTable:
/** ReadonlyArray<PickerCandidate> from @morai/contracts — the ranked engine candidates. */
readonly candidates: readonly unknown[];
/** User-pasted calendars (same PickerCandidate shape), pinned above candidates in paste order. */
readonly pastedCandidates: readonly unknown[];
readonly selectedId: string;
readonly combinedIds: ReadonlySet<string>;
readonly sort: { readonly key: "score" | "debit" | "theta"; readonly dir: "asc" | "desc" };
readonly onSortChange: (key: "score" | "debit" | "theta") => void;
/** Receives the PickerCandidate for the clicked row. */
readonly onSelect: (candidate: never) => void;
readonly onToggleCombine: (candidate: never) => void;
readonly onRemovePasted: (candidate: never) => void;
/** Scroll-container classes — desktop caps height, mobile scrolls horizontally. */
readonly wrapperClassName: string;
readonly tableClassName?: string;
readonly wrapperTestId?: string;

dtsPropsFor.EntryExitPlan:
/** PickerCandidate from @morai/contracts. */
readonly candidate: unknown;
/** VIX-tiered sizing from the snapshot — omitted renders "No recommendation", never a fabricated size. */
readonly sizing?: { tier?: "crisis" | "low" | "normal" | "elevated"; contracts?: number; vix?: number };

dtsPropsFor.WhyPanel:
/** PickerCandidate from @morai/contracts. */
readonly candidate: unknown;
readonly gex: {
  netGammaAtSpot: number;
  nearTerm: { callWall?: number; putWall?: number; flip?: number };
  flip?: number;
  callWall?: number;
  putWall?: number;
  absGammaStrike?: number;
};

dtsPropsFor.TermStructureChart:
readonly termStructure: readonly { dte: number; iv: number }[];
readonly events: readonly { date: string; name: string }[];
/** ISO 8601 snapshot reference date the DTE fields are relative to. */
readonly asOf: string;
/** PickerCandidate from @morai/contracts — its two legs are pinned on the curve. */
readonly candidate: unknown;
